      "arFull": "قُلْ اِنِّیْ نُهِیْتُ اَنْ اَعْبُدَ الَّذِیْنَ تَدْعُوْنَ مِنْ دُوْنِ اللّٰهِ ؕ قُلْ لَّاۤ اَتَّبِعُ اَهْوَآءَكُمْ ۙ قَدْ ضَلَلْتُ اِذًا وَّمَاۤ اَنَا مِنَ الْمُهْتَدِیْنَ ۟",
